"""Editorial notes checked against cached ISBN-matched publisher descriptions."""
from build_pilot import entry, run, group

N={}
def add(isbn,summary,story,series,pos,issues,guests=(),note='',alternative=False,coverage='Collected storyline',starting=False):
    N[isbn]=entry(summary,[story],run(series,pos,note,alternative),issues,guests,starting,coverage)

add('9781302497415','Early magazine adventures confront Marc with threats tied to espionage, a killer he suspects is his brother, and a terrorist claiming his own heroic identity. Frenchie and Marlene feature alongside a Hulk appearance.','Countdown to Dark','Moon Knight — early magazine stories',1,[],('Hulk',),'Independent collection of material from Hulk Magazine 13–15, 17–18, 20–21 and Marvel Preview 21. Shares some magazine material with Bad Moon Rising; partial stories are not indexed as whole-issue overlaps.',coverage='Early magazine anthology')

R='Moon Knight (2006)'
for isbn,pos,title,first,last,summary,guests in [
 ('9780785180203',1,'The Bottom',1,6,'Marc Spector struggles to return to vigilantism after his life has fallen apart. His dependence on Khonshu makes the hoped-for comeback a troubling bargain rather than a clean new beginning.',()),
 ('9781302368203',2,'Midnight Sun',7,13,'Marc’s return attracts scrutiny from other heroes while a brutal adversary leaves bodies and messages at familiar crime scenes. The threat is personal, and Moon Knight must confront someone who knows his history.',('Spider-Man','Punisher','Captain America')),
 ('9781302481964',3,'God & Country',14,20,'Moon Knight’s violent methods test the limits of his official registration. Tony Stark faces growing pressure to act as Marc leaves a trail that the Initiative can no longer ignore.',('Iron Man',)),
 ('9781302482626',4,'The Death of Marc Spector',21,25,'Norman Osborn unleashes the Thunderbolts against Moon Knight, forcing Marc to find a desperate way out. A separate holiday story follows his pursuit of hitmen on Christmas Eve.',('Thunderbolts','Norman Osborn')),
 ('9781302485924',5,'Down South',26,30,'Hiding in Mexico City, Moon Knight becomes involved in a kidnapping and a confrontation with corrupt police. The Punisher’s presence turns the rescue into a collision between two uncompromising vigilantes.',('Punisher',))]:
    add(isbn,summary,title,R,pos,group('Moon Knight',2006,first,last),guests,'Follow numbered volumes in this 2006 series; then Vengeance of the Moon Knight (2009).',starting=pos==1)
N['9781302482626']['contentsNote']='Also contains Moon Knight: Silent Knight #1; that bonus issue is not included in the overlap index.'

add('9781302514075','Marc moves to Los Angeles and becomes entangled in a criminal scheme involving Ultron’s inert body. Versions of familiar Avengers appear inside his mind, complicating his attempt to confront the threat.','Bendis & Maleev complete run','Moon Knight — Bendis & Maleev (2011)',1,group('Moon Knight',2011,1,12),note='Complete run; overlaps Volume 2. The Avengers described in the synopsis are mental manifestations, not verified physical guest appearances.',alternative=True,coverage='Complete run',starting=True)
add('9781302368197','Marc’s television project causes friction with Marlene while his conflict with Los Angeles’s criminal leadership escalates. This concluding volume brings the fight over the city to a costly climax.','Los Angeles showdown','Moon Knight — Bendis & Maleev (2011)',2,[],note='Concluding volume. Catalog lists issues 8–12; publisher synopsis does not confirm the range, so overlap indexing awaits verification.')
add('9781302515997','Marc wakes in an institution whose records contradict his memories. Competing identities and unsettling shifts in reality lead him toward an examination of his past and his connection to Khonshu.','Lunatic / Reincarnations / Birth and Death','Moon Knight — Lemire & Smallwood (2016)',1,group('Moon Knight',2016,1,14),note='Alternative edition of the complete Lemire run; overlaps the three smaller volumes and the other Complete Collection.',alternative=True,coverage='Complete run',starting=True)

E='Moon Knight — early collected history'
add('9781302405915','A collection of Moon Knight’s earliest appearances, spanning monster encounters, guest spots and the opening of his first solo series. Its contents reach across several titles rather than forming one continuous named arc.','Early appearances and solo-series launch',E,1,group('Moon Knight',1980,1,4)+group('Werewolf by Night',1972,32,33),note='First Epic Collection. The overlap index covers only the solo issues and Werewolf by Night; many additional guest appearances and magazine stories are included.',coverage='Early appearances anthology',starting=True)
add('9781302482541','Moon Knight encounters Stained Glass Scarlet, Morpheus and returning enemies while Marc’s competing identities complicate his work. A Daredevil encounter adds another vigilante to this stretch of the original series.','Shadows of the Moon',E,2,group('Moon Knight',1980,5,23),('Daredevil',),'Follows Bad Moon Rising.')
add('9781302507770','The original series moves toward its conclusion through encounters with Stained Glass Scarlet, Black Spectre and Werewolf by Night. A threat involving Marlene leads Marc to seek Doctor Strange’s help.','Final Rest',E,3,group('Moon Knight',1980,24,38),('Werewolf by Night','Doctor Strange'),'Follows Shadows of the Moon; concludes the 1980 series.')
add('9781302943493','Marc’s attempt to leave vigilantism behind ends when danger in Egypt draws him back to Khonshu. Renewed conflicts with Bushman and other enemies test both his heroic role and his relationship with Marlene.','Butcher’s Moon',E,4,group('Moon Knight',1985,1,6)+group('Marc Spector: Moon Knight',1989,1,7),('Brother Voodoo','Black Cat'),'Bridges the 1985 miniseries and the opening of Marc Spector: Moon Knight. Additional guest stories are not fully indexed.',coverage='Multiple series and guest stories')
add('9781302530006','Marc’s mercenary history leads to an accusation of murder while Bushman and the Secret Empire create fresh threats. Spider-Man and the Punisher become involved as he fights both his enemies and the consequences of his past.','The Trial of Marc Spector',E,5,group('Marc Spector: Moon Knight',1989,8,25),('Spider-Man','Punisher'),'Follows Butcher’s Moon. Also includes material from Punisher Annual #2.')
add('9781302534059','Stained Glass Scarlet’s return brings a bloody reckoning. Moon Knight also joins Spider-Man against a demonic Hobgoblin and becomes involved in a larger confrontation with a cybernetically enhanced enemy.','Scarlet Redemption',E,6,group('Marc Spector: Moon Knight',1989,26,38)+group('Amazing Spider-Man',1963,353,358),('Spider-Man','Punisher','Hobgoblin'),'Follows The Trial of Marc Spector; precedes Death Watch. Positions here describe story sequence, not printed Epic volume numbers.')
add('9781302526023','A mysterious illness threatens Marc’s life as encounters with Doctor Doom and the Infinity War complicate his search for help. He considers a successor while allies and enemies become entangled in his struggle to survive.','Death Watch',E,7,group('Marc Spector: Moon Knight',1989,39,51)+group('Web of Spider-Man',1985,93,94),('Doctor Doom','Doctor Strange','Spider-Man','Shang-Chi'),'Follows Scarlet Redemption. Includes Infinity War tie-ins, specials and additional material, not the complete Infinity War event.',coverage='Collected run with event tie-ins')

L='Moon Knight — Max Bemis / Legacy (2017)'
add('9781302504380','The Sun King threatens Marc’s role as Khonshu’s champion while another enemy, the Truth, attacks vulnerable people. Bushman’s involvement and a secret kept by Jake Lockley make the conflict painfully personal.','Crazy Runs in the Family',L,1,group('Moon Knight',2017,188,193),('Sun King','Bushman'),'Start this two-volume run here, or choose its Complete Collection.',starting=True)
add('9781302507787','A traumatic part of Marc’s childhood resurfaces as he confronts the Collective and other disturbing threats. The run moves toward a confrontation with old enemies and the forces shaping his identities.','Phases',L,2,group('Moon Knight',2017,194,200),note='Read after Crazy Runs in the Family; also contained in Legacy: The Complete Collection.')
add('9781302941314','The full Legacy run follows Marc’s conflict with the Sun King, revelations involving Jake Lockley and a return to painful events in his past. It combines the material published separately as Crazy Runs in the Family and Phases.','Crazy Runs in the Family / Phases',L,1,group('Moon Knight',2017,188,200),('Sun King','Bushman'),'Alternative to both smaller Legacy volumes.',True,'Complete run',True)

V='Vengeance of the Moon Knight (2009)'
add('9781302488765','Moon Knight returns to New York with new equipment and a renewed determination to act as a hero. His challenge to Norman Osborn brings him back into conflict with the man who drove him away.','Shock and Awe',V,1,group('Vengeance of the Moon Knight',2009,1,6),('Norman Osborn',),'Follows the 2006 Moon Knight series; distinct from Vengeance (2024).')
add('9781302488871','Deadpool is hired to kill a man who is already dying, and Moon Knight must decide whether to protect him. A classic magazine story accompanies this clash between the two vigilantes.','Killed, Not Dead',V,2,group('Vengeance of the Moon Knight',2009,7,9),('Deadpool',),'Follows Shock and Awe. Publisher lists issues 7–9 and Marvel Preview #21, while the catalog says 7–10; issue 10 is not treated as verified.')

M='Moon Knight — Midnight Mission continuation'
add('9781302529796','The Midnight Mission struggles to continue after Marc’s death. A mysterious new Moon Knight challenges the surviving allies, forcing Hunter’s Moon and the Mission to confront a familiar symbol turned against them.','New Moon',M,1,group('Vengeance of the Moon Knight',2024,1,4),('Hunter’s Moon',),'Read after The Last Days of Moon Knight (2021 series Volume 5).')
add('9781302531003','The struggle over Moon Knight’s identity collides with the vampire crisis of Blood Hunt. Hunter’s Moon, Tigra and the Mission defend New York while trying to secure a future for their community.','It’s Alive / Blood Hunt tie-in',M,2,group('Vengeance of the Moon Knight',2024,5,9),('Hunter’s Moon','Tigra'),'Read after New Moon. Ties into Blood Hunt; does not collect the main event.',coverage='Event tie-in and run conclusion')
add('9781302532642','Marc returns to a Midnight Mission that changed during his absence. Rejoining his allies brings immediate conflict with dangerous forces willing to endanger everyone around them.','Leave Home',M,3,group('Moon Knight: Fist of Khonshu',2024,0,5),note='Fist of Khonshu Volume 1; follows Vengeance (2024) and the Blood Hunt period.')
add('9781302534066','A fractured team and a difficult reckoning with Khonshu leave Marc under pressure. Meanwhile, 8-Ball faces the temptation of a new criminal crew and Carver brings another violent threat to the Mission.','Subterranean Jungle',M,4,group('Moon Knight: Fist of Khonshu',2024,6,10),('8-Ball','Carver'),'Fist of Khonshu Volume 2; follows Leave Home.')
add('9781302535384','Returning figures complicate life for Marc and his identities as the Mission faces another crisis. When the Wrecker seeks help with ghosts from his past, Moon Knight must decide whether an enemy deserves his assistance.','We’re Outta Here',M,5,group('Moon Knight: Fist of Khonshu',2024,11,15),('Wrecker',),'Fist of Khonshu Volume 3; follows Subterranean Jungle. Story title comes from the ISBN-matched bibliographic title.')

add('9781302940959','A sampler spanning Moon Knight’s debut as a werewolf hunter, encounters with Daredevil and Spider-Man, and a time-travel conflict involving Kang. It offers several different periods of the character rather than a single continuous story.','Origins, team-ups and a Kang encounter','Moon Knight — standalone samplers',1,group('Werewolf by Night',1972,32,33)+group('Moon Knight',1980,13,13),('Werewolf by Night','Daredevil','Spider-Man','Kang'),'Independent sampler. Includes annual material and a partial Spider-Man story; overlap indexing is incomplete.',coverage='Cross-era anthology',starting=True)
add('9781302523688','Different creative teams explore Moon Knight through short stories rendered in black, white and red. The collection includes future incarnations, an adventure with Spider-Man and a request for Doctor Strange’s assistance.','Black, White & Blood','Moon Knight — Black, White & Blood',1,group('Moon Knight: Black, White & Blood',2022,1,4),('Spider-Man','Doctor Strange'),'Standalone anthology; no single place in the main reading chronology.',coverage='Complete anthology')
add('9781302532000','Stories explore Marc alongside other bearers of the Moon Knight identity across different eras. Historical and future Fists of Khonshu broaden the mythology beyond one hero’s life.','Phases of the Moon Knight','Moon Knight — Phases anthology',1,[],note='Standalone anthology of incarnations. Publisher confirms issues 1–4 but its bibliographic series year is not used as an original issue year.',coverage='Complete anthology')
